    private void getOccupancyReport(io.javalin.http.Context ctx) {
        try {
            String dateStr = ctx.queryParam("date");
            if (dateStr == null) {
                ctx.status(400).json(error("INVALID_REQUEST", "Parâmetro date é obrigatório"));
                return;
